318		submitted[0].Subject = "nobody"
319		if d := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")); !d.Allowed {
320			t.Fatalf("published content changed by caller mutation: %+v", d)
321		}
322		// Mutating a query result must not change published content either.
323		got, err := s.Policies("acme", 1)
324		if err != nil {
325			t.Fatal(err)
326		}
327		got[0].Effect = EffectDeny
328		got[0].Subject = "nobody"
329		if d := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")); !d.Allowed {
330			t.Fatalf("published content changed by query-result mutation: %+v", d)
331		}
332	}
