334	func TestReviewPinsHistoricalVersion(t *testing.T) {
335		s := NewStore()
336		v1, err := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
337		if err != nil {
338			t.Fatal(err)
339		}
340		req := request("acme", "u1", "r1", "org/a", "read")
341		before := s.Review("acme", v1, req)
342		if !before.Allowed || before.Version != v1 {
343			t.Fatalf("review before changes: %+v", before)
344		}
345		// Later publish and rollback must not change the review of v1.
346		if _, err := s.Publish("acme", v1, nil); err != nil {
347			t.Fatal(err)
348		}
349		if _, err := s.Rollback("acme", 2, 2); err != nil {
350			t.Fatal(err)
351		}
352		after := s.Review("acme", v1, req)
353		if !reflect.DeepEqual(before, after) {
354			t.Fatalf("review changed after later publishes: before=%+v after=%+v", before, after)
355		}
356		// A version that does not exist denies with a reason, no silent fallback.
357		d := s.Review("acme", 99, req)
358		if d.Allowed || d.Version != 0 {
359			t.Fatalf("review of missing version: %+v", d)
360		}
361		if d := s.Review("acme", 0, req); d.Allowed {
362			t.Fatalf("review of version 0 must deny: %+v", d)
363		}
364	}
365	
366	func TestOrganizationsAreIndependent(t *testing.T) {
367		s := NewStore()
368		// Same subject, resource and policy identifiers in two organizations.
369		if _, err := s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)}); err != nil {
370			t.Fatal(err)
371		}
372		if _, err := s.Publish("globex", 0, nil); err != nil {
373			t.Fatal(err)
374		}
375		if d := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read")); !d.Allowed {
376			t.Fatalf("acme decision: %+v", d)
377		}
378		if d := s.Decide("globex", request("globex", "u1", "r1", "org/a", "read")); d.Allowed {
379			t.Fatalf("globex decision leaked acme policy: %+v", d)
380		}
381		// Versions advance independently.
382		v, err := s.Publish("globex", 1, nil)
383		if err != nil || v != 2 {
384			t.Fatalf("globex second publish = %d, %v; want 2, nil", v, err)
385		}
386		if got := s.CurrentVersion("acme"); got != 1 {
387			t.Fatalf("acme current = %d, want 1", got)
388		}
389	}
